Versión **in-place**:

```js
function quicksort(arr, inicio = 0, fin = arr.length - 1) {
  if (inicio >= fin) return arr;

  const indicePivote = particionar(arr, inicio, fin);

  quicksort(arr, inicio, indicePivote - 1);
  quicksort(arr, indicePivote + 1, fin);

  return arr;
}

function particionar(arr, inicio, fin) {
  const pivote = arr[fin];
  let i = inicio;

  for (let j = inicio; j < fin; j++) {
    if (arr[j] <= pivote) {
      [arr[i], arr[j]] = [arr[j], arr[i]];
      i++;
    }
  }

  [arr[i], arr[fin]] = [arr[fin], arr[i]];

  return i;
}

const numeros = [5, 3, 8, 4, 2, 7, 1];

quicksort(numeros);

console.log(numeros);
// [1, 2, 3, 4, 5, 7, 8]
```

Quicksort **no recursivo** en JavaScript usando una pila:

```js
function quicksortIterativo(arr) {
  if (arr.length <= 1) return arr;

  const pila = [];
  pila.push([0, arr.length - 1]);

  while (pila.length > 0) {
    const [inicio, fin] = pila.pop();

    if (inicio >= fin) continue;

    const indicePivote = particionar(arr, inicio, fin);

    // Subarray izquierdo
    pila.push([inicio, indicePivote - 1]);

    // Subarray derecho
    pila.push([indicePivote + 1, fin]);
  }

  return arr;
}

function particionar(arr, inicio, fin) {
  const pivote = arr[fin];
  let i = inicio;

  for (let j = inicio; j < fin; j++) {
    if (arr[j] <= pivote) {
      [arr[i], arr[j]] = [arr[j], arr[i]];
      i++;
    }
  }

  [arr[i], arr[fin]] = [arr[fin], arr[i]];

  return i;
}

const numeros = [5, 3, 8, 4, 2, 7, 1];

quicksortIterativo(numeros);

console.log(numeros);
// [1, 2, 3, 4, 5, 7, 8]
```

